export type IoName = keyof typeof IO
export type LuName = keyof typeof LU

interface Props { size?: number; className?: string; style?: CSSProperties; strokeWidth?: number; title?: string }

/** A phone-side glyph (Ionicons). */
export function Io({ name, size = 20, className, style }: Props & { name: IoName }) {
  const g = IO[name] as Glyph
  return (
    <svg viewBox={g[0]} width={size} height={size} className={className} style={style} aria-hidden="true"
      fill="currentColor" stroke="currentColor" strokeWidth={0} dangerouslySetInnerHTML={{ __html: g[2] }} />
  )
}

/** An editor glyph (Lucide). */
export function Lu({ name, size = 18, className, style, strokeWidth = 1.75, title }: Props & { name: LuName }) {
  const g = LU[name] as Glyph
  return (
    <svg viewBox={g[0]} width={size} height={size} className={className} style={style} aria-hidden={title ? undefined : 'true'}
      fill="none" stroke="currentColor" strokeWidth={strokeWidth} strokeLinecap="round" strokeLinejoin="round"
      dangerouslySetInnerHTML={{ __html: (title ? `<title>${title}</title>` : '') + g[2] }} />
  )
}
